const input=$json.body??$json;
const arr=v=>Array.isArray(v)?v:[];
const truthy=v=>v===true||v==="true"||v===1||v==="1";
const milestones=arr(input.milestones);
const blockers=arr(input.blockers);
const launch=input.launch_evidence??{};
const execution=input.execution??{};
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const launchConfirmed=truthy(input.execution_launch_ready)||truthy(input.execution_launched)||["launched","active","confirmed"].includes(String(launch.status||"").toLowerCase());
const launchKey=String(input.launch_idempotency_key||input.execution_idempotency_key||"").trim();
const launchEvidenceKey=String(launch.idempotency_key||"").trim();
const duplicateSafe=Boolean(launchKey)&&( !launchEvidenceKey || launchEvidenceKey===launchKey );
const alreadyActive=truthy(input.closing_active)||truthy(execution.active)||["active","in_progress","closing_active"].includes(String(execution.status||"").toLowerCase());
const closingDate=input.closing_date?new Date(input.closing_date):null;
const closingDateValid=Boolean(input.closing_date)&&!Number.isNaN(closingDate?.getTime());
const blockersClear=blockers.length===0;
const incomplete=milestones.filter(m=>!truthy(m.completed)&&!["completed","done","verified"].includes(String(m.status||"").toLowerCase()));
const overdue=milestones.filter(m=>truthy(m.overdue)||["overdue","failed"].includes(String(m.status||"").toLowerCase()));
const criticalOverdue=overdue.filter(m=>truthy(m.critical)||String(m.priority||"").toLowerCase()==="critical");
const completed=incomplete.length===0&&milestones.length>0;
const active=identityComplete&&launchConfirmed&&duplicateSafe&&closingDateValid&&blockersClear;

let status="activation_required",nextWorkflow="WF-279",humanReview=false;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";humanReview=true;}
else if(!launchConfirmed){status="launch_not_confirmed";nextWorkflow="WF-278";humanReview=true;}
else if(!duplicateSafe){status="launch_identity_conflict";nextWorkflow="WF-126";humanReview=true;}
else if(!closingDateValid||!blockersClear){status="blocked";nextWorkflow="WF-126";humanReview=true;}
else if(alreadyActive){status="already_active";nextWorkflow=criticalOverdue.length?"WF-280":"WF-279";}
else if(active){status="closing_execution_activated";nextWorkflow=criticalOverdue.length?"WF-280":"WF-280";}
if(completed){status="milestones_completed";nextWorkflow="WF-281";}

return [{json:{...input,workflow:"WF-279",workflow_name:"Closing Execution Launch → Active Closing Milestone Orchestrator",status,closing_execution:{identity_complete:identityComplete,launch_confirmed:launchConfirmed,launch_idempotency_key_present:Boolean(launchKey),launch_evidence_key_matches:!launchEvidenceKey||launchEvidenceKey===launchKey,duplicate_safe:duplicateSafe,already_active:alreadyActive,closing_date_valid:closingDateValid,blockers_clear:blockersClear,milestone_count:milestones.length,incomplete_milestone_count:incomplete.length,overdue_milestone_count:overdue.length,critical_overdue_count:criticalOverdue.length,active,completed},next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:status,audit:{event_type:"closing_execution_activation_milestone_orchestration",idempotency_key:input.idempotency_key||`wf-279:${input.deal_id||"unknown"}:${launchKey||"none"}:${input.version||1}`}}}];
